<?php
declare(strict_types=1);
final class PluginManager {
    public function __construct(private readonly array $config){}
    private function builtins():array{return [
        ['name'=>'anchor-browser','version'=>'1.0.0','description'=>'Automação complexa de navegador por sessão local ou serviço remoto; requer configuração de endpoint.','requires_config'=>true,'tools'=>[['name'=>'browser_open','description'=>'Abrir URL autorizada'],['name'=>'browser_extract','description'=>'Extrair conteúdo de página'],['name'=>'browser_fill','description'=>'Preencher formulário com confirmação']]],
        ['name'=>'gmail','version'=>'1.0.0','description'=>'Pesquisar e resumir e-mails e preparar rascunhos; envio exige confirmação.','requires_config'=>true,'tools'=>[['name'=>'gmail_search','description'=>'Pesquisar mensagens'],['name'=>'gmail_read_thread','description'=>'Ler thread'],['name'=>'gmail_draft','description'=>'Criar rascunho']]],
        ['name'=>'google-workspace','version'=>'1.0.0','description'=>'Google Drive, Docs e Sheets por API configurada no painel.','requires_config'=>true,'tools'=>[['name'=>'drive_search','description'=>'Pesquisar arquivos no Drive'],['name'=>'drive_download','description'=>'Baixar arquivo'],['name'=>'drive_upload','description'=>'Enviar arquivo'],['name'=>'docs_read','description'=>'Ler documento'],['name'=>'sheets_read','description'=>'Ler planilha']]],
        ['name'=>'instagram','version'=>'1.0.0','description'=>'Preparar mídia e publicar no Instagram somente após confirmação.','requires_config'=>true,'tools'=>[['name'=>'instagram_prepare_post','description'=>'Preparar publicação'],['name'=>'instagram_publish','description'=>'Publicar com confirmação'],['name'=>'instagram_list_media','description'=>'Listar mídia']]],
        ['name'=>'github','version'=>'1.0.0','description'=>'Repositórios, arquivos, issues, branches e pull requests por token configurado.','requires_config'=>true,'tools'=>[['name'=>'github_repositories','description'=>'Listar repositórios'],['name'=>'github_read_file','description'=>'Ler arquivo'],['name'=>'github_search_code','description'=>'Pesquisar código'],['name'=>'github_issue','description'=>'Criar issue com confirmação'],['name'=>'github_pull_request','description'=>'Consultar pull request']]],
        ['name'=>'ftp','version'=>'1.0.0','description'=>'Transferência FTP com modo somente leitura ou leitura/escrita e confirmação destrutiva.','requires_config'=>true,'tools'=>[['name'=>'ftp_list','description'=>'Listar pasta'],['name'=>'ftp_download','description'=>'Baixar arquivo'],['name'=>'ftp_upload','description'=>'Enviar arquivo'],['name'=>'ftp_delete','description'=>'Excluir com confirmação']]],
        ['name'=>'api-rest-graphql','version'=>'1.0.0','description'=>'Chamadas REST e GraphQL definidas pelo usuário no painel de APIs.','requires_config'=>true,'tools'=>[['name'=>'api_request','description'=>'Executar requisição allowlisted'],['name'=>'api_graphql','description'=>'Executar consulta GraphQL allowlisted']]],
        ['name'=>'database-tools','version'=>'1.0.0','description'=>'Consultas MySQL/PostgreSQL com modo somente leitura por padrão.','requires_config'=>true,'tools'=>[['name'=>'db_schema','description'=>'Inspecionar schema'],['name'=>'db_query_readonly','description'=>'Executar consulta somente leitura']]],
        ['name'=>'authenticated-search','version'=>'1.0.0','description'=>'Busca web autenticada usando uma API configurada.','requires_config'=>true,'tools'=>[['name'=>'search_authenticated','description'=>'Pesquisar em serviço configurado']]],
        ['name'=>'automation-workflows','version'=>'1.0.0','description'=>'Fluxos entre serviços externos com etapas revisáveis.','requires_config'=>true,'tools'=>[['name'=>'workflow_preview','description'=>'Simular fluxo'],['name'=>'workflow_run','description'=>'Executar fluxo aprovado']]]
    ];}
    private function dir():string{$dir=$this->config['storage'].DIRECTORY_SEPARATOR.'plugins';if(!is_dir($dir))@mkdir($dir,0775,true);return $dir;}
    public function list():array{$files=[];foreach(glob($this->dir().DIRECTORY_SEPARATOR.'*.json')?:[] as $file){$data=json_decode((string)file_get_contents($file),true);if(is_array($data)&&isset($data['name']))$files[$data['name']]=$data;}$out=[];foreach($this->builtins() as $x)$out[]=$files[$x['name']]??array_merge($x,['enabled'=>false,'trusted'=>false,'builtin'=>true]);foreach($files as $name=>$x)if(!array_filter($this->builtins(),static fn($b)=>$b['name']===$name))$out[]=$x;return $out;}
    public function seed():array{$items=[];foreach($this->builtins() as $x){$x['enabled']=false;$x['trusted']=false;$x['builtin']=true;file_put_contents($this->dir().DIRECTORY_SEPARATOR.$x['name'].'.json',json_encode($x,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$items[]=$x['name'];}return $items;}
    public function install(array $manifest):array{$name=trim((string)($manifest['name']??''));if($name===''||!preg_match('/^[a-zA-Z0-9._-]{2,80}$/',$name))throw new InvalidArgumentException('Nome de plugin inválido.');$tools=(array)($manifest['tools']??[]);foreach($tools as $tool){if(!is_array($tool)||!preg_match('/^[a-zA-Z0-9._-]{2,80}$/',(string)($tool['name']??'')))throw new InvalidArgumentException('Manifesto de plugin inválido.');}$manifest['name']=$name;$manifest['version']=(string)($manifest['version']??'1.0.0');$manifest['enabled']=false;file_put_contents($this->dir().DIRECTORY_SEPARATOR.$name.'.json',json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));return ['name'=>$name,'enabled'=>false,'trusted'=>false];}
}
?>
